/*
 PLAN
 1. Composition: 3.2x2.2 rounded panel at z=0 on a 7x6 gradient backdrop (z=-2.5); ghost wireframe watch-card left-of-center, copy column right, red CTA bar below body; contact glow plane behind panel.
 2. Light rig: rig-soft-wrap — key dir #ffefdd 2.0 @ (1.8,2.2,2.8)*r, hemisphere fill #efe8de 0.5, rim dir #fff8f0 0.9 @ (-1,1.8,-2.4)*r, all node-local (rim capped, panel roughness high).
 3. Materials: panel = MeshStandardNodeMaterial with TSL radial gradient #14141a->#0b0b10 + 0.25-pitch hairline grid (paper @6%), roughness 0.55; ghost = basic paper strokes at low opacity; CTA = standard node material w/ vertical #ff4450->#c1121f gradient + edge emissive #ff2a38 (1.5).
 4. Motion: mount fade-up (y+0.2->0, 500ms power2.out), ghost opacity breathe 0.24<->0.34 2400ms sine yoyo, CTA press scale 0.97 120ms; all timelines killed in cleanup.
 5. Focal element: the accent CTA bar — the single brightest read; everything else graded below it.
*/
import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, vec3, vec4, mix, smoothstep, float, length, fract, abs, min, sub, mul } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const root = new THREE.Group();
  const timelines = [];
  const disposables = [];

  const colors = config.intent?.visualSpec?.colors ?? {};
  const C = {
    background: colors.background ?? '#0b0b10',
    surface: colors.surface ?? '#16161d',
    ink: colors.ink ?? '#16161d',
    paper: colors.paper ?? '#e8ecf2',
    accent: colors.accent ?? '#ff2a38',
    grad0: colors.gradientStops?.[0]?.hex ?? '#14141a',
    grad1: colors.gradientStops?.[1]?.hex ?? '#0b0b10',
  };
  const col = (hex) => { const c = new THREE.Color(hex); return vec3(c.r, c.g, c.b); };

  // ---------- backdropStage: 7x6 vertical gradient plane, never void ----------
  const backdropGeo = new THREE.PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  {
    const v = uv().y;
    backdropMat.colorNode = mix(col(C.grad1), col(C.grad0), smoothstep(0.0, 1.0, v));
  }
  const backdrop = new THREE.Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // ---------- lightRig: rig-soft-wrap, subject radius ~1.6 ----------
  const r = 1.6;
  const key = new THREE.DirectionalLight('#ffefdd', 1.4); // grazing key (panel high-albedo text regions; keep <=1.5 node-local)
  key.position.set(1.8 * r, 2.2 * r, 2.8 * r);
  key.target.position.set(0, 0.5, 0);
  const fill = new THREE.HemisphereLight('#efe8de', '#0b0b10', 0.5);
  const rim = new THREE.DirectionalLight('#fff8f0', 0.9);
  rim.position.set(-1 * r, 1.8 * r, -2.4 * r);
  rim.target.position.set(0, 0.5, 0);
  root.add(key, key.target, fill, rim, rim.target);

  // ---------- panelSurface: 3.2x2.2, radial gradient + hairline grid + rounded corners + hairline border ----------
  const PW = 3.2, PH = 2.2, RAD = 0.06;
  const panelGeo = new THREE.PlaneGeometry(PW, PH);
  const panelMat = new MeshStandardNodeMaterial({ roughness: 0.55, metalness: 0.15, transparent: true });
  {
    const u = uv();
    // scene-unit coords centered
    const px = u.x.sub(0.5).mul(PW);
    const py = u.y.sub(0.5).mul(PH);
    // rounded-rect SDF
    const hw = float(PW / 2 - RAD), hh = float(PH / 2 - RAD);
    const qx = abs(px).sub(hw).max(0.0);
    const qy = abs(py).sub(hh).max(0.0);
    const d = length(vec2(qx, qy)).sub(RAD);
    const inside = smoothstep(0.004, -0.004, d);
    const border = smoothstep(0.006, 0.0, abs(d)).mul(inside.oneMinus().oneMinus()); // hairline at edge
    // radial engineered gradient center->edges
    const radial = length(vec2(px.div(PW), py.div(PH))).mul(2.0).clamp(0.0, 1.0);
    let base = mix(col(C.grad0), col(C.grad1), radial);
    // hairline grid, 0.25 pitch, paper @ 6%
    const gx = abs(fract(px.div(0.25)).sub(0.5)).mul(0.25);
    const gy = abs(fract(py.div(0.25)).sub(0.5)).mul(0.25);
    const line = smoothstep(0.006, 0.002, min(gx, gy));
    base = mix(base, col(C.paper), line.mul(0.06));
    // border #26262f hairline
    const bc = new THREE.Color('#26262f');
    base = mix(base, vec3(bc.r, bc.g, bc.b), border);
    panelMat.colorNode = base;
    panelMat.opacityNode = inside;
  }
  const panel = new THREE.Mesh(panelGeo, panelMat);
  panel.position.set(0, 0, 0);
  root.add(panel);
  disposables.push(panelGeo, panelMat);

  // subtle accent floor glow behind panel (depth plane 3)
  const glowGeo = new THREE.PlaneGeometry(4.2, 3.0);
  const glowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  {
    const u = uv();
    const dd = length(u.sub(vec2(0.5, 0.5)).mul(vec2(2.0, 2.0)));
    glowMat.colorNode = col(C.accent);
    glowMat.opacityNode = smoothstep(1.0, 0.0, dd).mul(0.05);
  }
  const glow = new THREE.Mesh(glowGeo, glowMat);
  glow.position.set(0, -0.3, -0.6);
  root.add(glow);
  disposables.push(glowGeo, glowMat);

  // ---------- ghostPreview: wireframe watch-card, left of center ----------
  const ghost = new THREE.Group();
  const ghostMats = [];
  const stroke = 0.008;
  const paperC = new THREE.Color(C.paper);
  const mkGhostMat = (op) => {
    const m = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
    m.colorNode = vec3(paperC.r, paperC.g, paperC.b);
    m.opacity = op;
    ghostMats.push(m);
    disposables.push(m);
    return m;
  };
  // card outline 1.1 x 1.4 as four hairline bars
  const outlineMat = mkGhostMat(0.30);
  const GW = 1.1, GH = 1.4;
  const barH = new THREE.PlaneGeometry(GW, stroke);
  const barV = new THREE.PlaneGeometry(stroke, GH);
  disposables.push(barH, barV);
  const eTop = new THREE.Mesh(barH, outlineMat); eTop.position.y = GH / 2;
  const eBot = new THREE.Mesh(barH, outlineMat); eBot.position.y = -GH / 2;
  const eL = new THREE.Mesh(barV, outlineMat); eL.position.x = -GW / 2;
  const eR = new THREE.Mesh(barV, outlineMat); eR.position.x = GW / 2;
  ghost.add(eTop, eBot, eL, eR);
  // ghost dial circle, 0.55 diameter ring
  const ringGeo = new THREE.RingGeometry(0.275 - stroke, 0.275, 64);
  disposables.push(ringGeo);
  const dial = new THREE.Mesh(ringGeo, mkGhostMat(0.30));
  dial.position.set(0, 0.22, 0.001);
  ghost.add(dial);
  // two ghost text bars 0.7 x 0.06 at 22%
  const tbGeo = new THREE.PlaneGeometry(0.7, 0.06);
  disposables.push(tbGeo);
  const tbMat = mkGhostMat(0.22);
  const tb1 = new THREE.Mesh(tbGeo, tbMat); tb1.position.set(0, -0.30, 0.001);
  const tb2 = new THREE.Mesh(tbGeo, tbMat); tb2.position.set(0, -0.44, 0.001);
  ghost.add(tb1, tb2);
  ghost.position.set(-0.85, 0.05, 0.01);
  root.add(ghost);

  // ghost breathe: opacity 0.24 -> 0.34, 2400ms sine yoyo
  const breatheProxy = { k: 0.24 / 0.30 };
  const baseOps = ghostMats.map((m) => m.opacity);
  const breathe = gsap.to(breatheProxy, {
    k: 0.34 / 0.30, duration: 2.4, ease: 'sine.inOut', yoyo: true, repeat: -1,
    onUpdate: () => { ghostMats.forEach((m, i) => { m.opacity = baseOps[i] * breatheProxy.k; }); },
  });
  timelines.push(breathe);

  // ---------- copyColumn: headline, body, right of ghost ----------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const byRole = (role, fb) => (items.find((i) => i.role === role)?.text) ?? fb;
  const copyX = 0.28;
  const headline = ctx.fontAtlas.createText(byRole('headline', 'Your ledger is empty.'), {
    fontSize: 34, color: C.paper, align: 'left', maxWidthPx: 300,
  });
  headline.position.set(copyX, 0.55, 0.01);
  root.add(headline);
  const body = ctx.fontAtlas.createText(byRole('body', 'Commissioned pieces and saved references will appear here once you begin.'), {
    fontSize: 13, color: '#b7bec9', align: 'left', maxWidthPx: 280,
  });
  body.position.set(copyX, 0.12, 0.01);
  root.add(body);

  // ---------- ctaButton: 1.5 x 0.36 accent gradient bar with emissive edge (FOCAL) ----------
  const cta = new THREE.Group();
  const ctaGeo = new THREE.BoxGeometry(1.5, 0.36, 0.05);
  const ctaMat = new MeshStandardNodeMaterial({ roughness: 0.5, metalness: 0.2 });
  {
    const t0 = new THREE.Color('#c1121f'), t1 = new THREE.Color('#ff4450');
    ctaMat.colorNode = mix(vec3(t0.r, t0.g, t0.b), vec3(t1.r, t1.g, t1.b), uv().y);
    // edge emissive #ff2a38 intensity 1.5
    const eu = uv();
    const edge = smoothstep(0.08, 0.0, min(min(eu.x, eu.x.oneMinus()), min(eu.y, eu.y.oneMinus())));
    ctaMat.emissiveNode = col(C.accent).mul(edge.mul(1.5));
  }
  const ctaMesh = new THREE.Mesh(ctaGeo, ctaMat);
  cta.add(ctaMesh);
  disposables.push(ctaGeo, ctaMat);
  const ctaLabel = ctx.fontAtlas.createText(byRole('cta-label', 'BROWSE THE COLLECTION'), {
    fontSize: 13, color: C.ink, align: 'center', letterSpacingPx: 1.04,
  });
  ctaLabel.position.set(0, 0, 0.03);
  cta.add(ctaLabel);
  cta.position.set(copyX + 0.55, -0.42, 0.04);
  root.add(cta);

  // ---------- contactShadow under CTA (grounding read on panel) ----------
  const shGeo = new THREE.PlaneGeometry(1.9, 0.5);
  const shMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  {
    const dd = length(uv().sub(vec2(0.5, 0.5)).mul(vec2(2.2, 2.2)));
    shMat.colorNode = vec3(0, 0, 0);
    shMat.opacityNode = smoothstep(1.0, 0.0, dd).mul(0.45);
  }
  const sh = new THREE.Mesh(shGeo, shMat);
  sh.position.set(copyX + 0.55, -0.52, 0.015);
  root.add(sh);
  disposables.push(shGeo, shMat);

  // ---------- mountFadeUp: opacity via scale-safe y + material fade ----------
  root.position.y = 0.2;
  const fadeMats = [panelMat, glowMat, shMat, ctaMat, ...ghostMats];
  const mountProxy = { t: 0 };
  fadeMats.forEach((m) => { m.transparent = true; });
  const mount = gsap.timeline();
  mount.to(root.position, { y: 0, duration: 0.5, ease: 'power2.out' }, 0);
  mount.from(root.scale, { x: 0.98, y: 0.98, z: 0.98, duration: 0.5, ease: 'power2.out' }, 0);
  mount.to(mountProxy, { t: 1, duration: 0.5, ease: 'power2.out' }, 0);
  timelines.push(mount);

  // ---------- primitives (spec lists none, apply defensively) ----------
  const primHandles = [];
  for (const p of config.cinematicPrimitives ?? []) {
    const fn = ctx.primitives[p.name];
    if (fn) primHandles.push(fn(root, p.params));
  }

  // ---------- interactions: CTA press + navigate ----------
  root.userData.handlers = {
    click: (hit) => {
      const press = gsap.timeline();
      press.to(cta.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(1.7)' });
      press.to(cta.scale, { x: 1, y: 1, z: 1, duration: 0.25, ease: 'power2.out' });
      timelines.push(press);
      ctx.emit('navigate', { to: 'hub-collection' });
    },
    hover: () => {
      const h = gsap.to(cta.rotation, { x: -0.05, duration: 0.3, ease: 'power2.out' });
      timelines.push(h);
    },
    hoverOut: () => {
      const h = gsap.to(cta.rotation, { x: 0, duration: 0.3, ease: 'power2.out' });
      timelines.push(h);
    },
  };

  root.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    primHandles.forEach((h) => h.cleanup && h.cleanup());
    disposables.forEach((d) => d.dispose && d.dispose());
    [headline, body, ctaLabel].forEach((t) => {
      t.traverse?.((o) => {
        o.geometry?.dispose?.();
        o.material?.dispose?.();
      });
    });
  };

  return root;
}

/* @spec-manifest
{"elements":[
{"id":"text.headline.0","where":"copyColumn","how":"fontAtlas headline 34px paper left-aligned"},
{"id":"text.body.1","where":"copyColumn","how":"fontAtlas body 13px muted paper"},
{"id":"text.cta-label.2","where":"ctaButton","how":"fontAtlas ink label on CTA"},
{"id":"color.background","where":"backdropStage","how":"gradient stop grad1 = background"},
{"id":"color.surface","where":"panelSurface","how":"surface family via grad0/border tones"},
{"id":"color.ink","where":"ctaButton","how":"CTA label color C.ink"},
{"id":"color.paper","where":"ghostPreview","how":"ghost strokes and grid lines paper"},
{"id":"color.accent","where":"ctaButton","how":"CTA edge emissive #ff2a38 1.5"},
{"id":"color.gradient","where":"backdropStage","how":"vertical 2-stop #14141a to #0b0b10"},
{"id":"effects.spec","where":"panelSurface","how":"radial gradient, 0.25 grid, rounded border"}
]}
*/
